/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  console.log(getResult(line));
});

function getResult(s) {
  const ip = s.split("#");

  // ip地址由四部分组成，少于或多于四部分都不合法
  if (ip.length != 4) {
    return "invalid IP";
  }

  // 如果ip地址四部分某部分不合法，则ip不合法
  if (
    !isValid(ip[0], 1, 128) ||
    !isValid(ip[1], 0, 255) ||
    !isValid(ip[2], 0, 255) ||
    !isValid(ip[3], 0, 255)
  ) {
    return "invalid IP";
  }

  // JS的数值安全范围最大时2^53，因此不用担心整型溢出问题
  return parseInt(
    getHexStr(ip[0]) + getHexStr(ip[1]) + getHexStr(ip[2]) + getHexStr(ip[3]),
    16
  );
}

// ip组成是否合法
function isValid(s, from, to) {
  // 如果包含非数字字符，则不合法
  if (/[^0-9]/.test(s)) return false;

  // 如果包含前导0，则不和法，如012
  const num = parseInt(s);
  if (num + "" != s) return false;

  // 如果不是规定范围，则不合法
  return num >= from && num <= to;
}

// 获取十进制数字符串对应的十六进制数字符串
function getHexStr(s) {
  let hexStr = parseInt(s).toString(16);
  // 补足前导0
  if (hexStr.length < 2) hexStr = "0" + hexStr;
  return hexStr;
}
